public static int calculateMaxServings(int N, int[] Qi, int[] Ai, int[] Bi) {
    final int MAXMAKE = 1000000;
    int maxServings = 0;

    for (int x = 0; x < MAXMAKE; x++) {
        boolean canMake = true;
        for (int i = 0; i < N; i++) {
            if (Qi[i] - Ai[i] * x < 0) {
                canMake = false;
                break;
            }
        }
        if (!canMake) break;

        int canY = Integer.MAX_VALUE;
        for (int i = 0; i < N; i++) {
            if (Bi[i] == 0) continue;
            canY = Math.min(canY, (Qi[i] - Ai[i] * x) / Bi[i]);
        }
        maxServings = Math.max(maxServings, x + canY);
    }

    return maxServings;
}
